        code: "// A tool definition is documentation the model reads. Write it that way.\nexport const ordersSearch = {\n  name: 'orders_search',\n  description: [\n    'Search orders for one customer. Use this to find an order id before calling',\n    'orders_get or refund_create. Returns at most 20 matches, newest first, as',\n    'id plus a one-line summary — call orders_get for the full record.',\n    'Do not use this to list every order in the system; it is always scoped to one customer.',\n  ].join(' '),\n  input_schema: {\n    type: 'object',\n    properties: {\n      customer_email: { type: 'string', format: 'email', description: 'Exact email of the customer.' },\n      status: { type: 'string', enum: ['pending', 'shipped', 'delivered', 'cancelled'] },\n      limit: { type: 'integer', minimum: 1, maximum: 20, default: 10 },\n    },\n    required: ['customer_email'],\n    additionalProperties: false,\n  },\n  annotations: { readOnlyHint: true },   // lets the host parallelise reads\n} as const;\n\n// The result: small, stable, and honest about what was omitted.\nexport async function runOrdersSearch(input: { customer_email: string; status?: string; limit?: number }) {\n  const limit = input.limit ?? 10;\n  const rows = await db.orders.find(input, limit + 1);\n  if (input.status && !ordersSearch.input_schema.properties.status.enum.includes(input.status)) {\n    // An error the model can act on next turn, not a stack trace.\n    return { error: `Unknown status \"${input.status}\". Valid values: pending, shipped, delivered, cancelled.` };\n  }\n  return {\n    matches: rows.slice(0, limit).map(o => ({ id: o.id, summary: `${o.placed_at.slice(0, 10)} · ${o.status} · ₹${o.total} · ${o.item}` })),\n    truncated: rows.length > limit,       // say so, rather than silently dropping\n    next_step: 'Call orders_get with one id for the full record.',\n  };\n}\n\n// Writes assume a retry: the same key twice is one refund.\nexport const refundCreate = {\n  name: 'refund_create',\n  description: 'Refund one order. Requires an idempotency_key; repeating a key returns the original refund instead of creating a second one.',\n  input_schema: {\n    type: 'object',\n    properties: {\n      order_id: { type: 'string' },\n      amount_paise: { type: 'integer', minimum: 1 },\n      idempotency_key: { type: 'string', minLength: 8 },\n    },\n    required: ['order_id', 'amount_paise', 'idempotency_key'],\n    additionalProperties: false,\n  },\n} as const;",
