        code: "// Structured note-taking: memory the agent owns, outside the context window.\nconst NOTES = 'NOTES.md';\n\nconst writeNote = {\n  name: 'notes_append',\n  description: 'Append one finding or decision to NOTES.md. Write after each completed step so work survives a context reset. Keep entries to one or two lines.',\n  input_schema: {\n    type: 'object',\n    properties: { entry: { type: 'string', maxLength: 400 } },\n    required: ['entry'], additionalProperties: false,\n  },\n} as const;\n\n// Just-in-time retrieval: hold identifiers, fetch content only when needed.\nconst searchDocs = {\n  name: 'docs_search',\n  description: 'Search the corpus. Returns up to 10 { path, heading, snippet } matches. Call docs_read with a path to load one section in full.',\n  input_schema: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'], additionalProperties: false },\n  annotations: { readOnlyHint: true },\n} as const;\n\n// Delegation: a focused subagent returns a summary, not its transcript.\nasync function researchWithSubagent(question: string) {\n  const result = await runAgent({\n    system: 'You research one question and return at most 8 lines: findings, each with its source path.',\n    tools: [searchDocs, readDocs],      // a minimal tool surface for this job\n    messages: [{ role: 'user', content: question }],\n    maxTurns: 8,\n  });\n  return result.text;                    // the parent's context grows by 8 lines\n}\n\n// Resuming after compaction: re-read durable state rather than trusting history.\nasync function resume(goal: string) {\n  const notes = await readFile(NOTES).catch(() => '');\n  return runAgent({\n    system: 'Continue the task. NOTES.md is the record of what is already done; do not repeat completed work.',\n    messages: [{ role: 'user', content: `Goal: ${goal}\\n\\nNOTES.md:\\n${notes}` }],\n    tools: [searchDocs, readDocs, writeNote],\n  });\n}",
