        code: "// Orchestrator-workers with structured hand-offs and bounded workers.\ntype WorkerResult = {\n  subtask: string;\n  findings: string[];\n  sources: string[];\n  confidence: 'high' | 'medium' | 'low';\n  gaps: string[];          // what the worker could NOT establish\n};\n\nasync function orchestrate(goal: string) {\n  // 1. Decompose at run time: the subtasks are not known in advance.\n  const plan = await planner(goal);                       // => string[] of subtasks\n\n  // 2. Fan out only read-only work; each worker is bounded and minimal.\n  const results = await Promise.all(plan.map(subtask => runWorker({\n    system: 'Investigate ONE subtask. Return JSON matching WorkerResult. Cite a source path for every finding. List what you could not establish under gaps.',\n    tools: [docsSearch, docsRead],                        // read-only: safe in parallel\n    maxTurns: 8,\n    messages: [{ role: 'user', content: subtask }],\n    responseFormat: 'json',\n  }) as Promise<WorkerResult>));\n\n  // 3. Synthesise mechanically where possible, and escalate real conflicts.\n  const cited = results.filter(r => r.sources.length > 0);\n  const unresolved = results.flatMap(r => r.gaps);\n  const conflicts = findContradictions(cited);\n  if (conflicts.length) return { status: 'needs_review', conflicts, results };\n\n  return { status: 'ok', summary: await synthesise(goal, cited), unresolved };\n}\n\n// Exposing one capability over MCP so any compliant host can use it.\n// server.ts — protocol version 2026-07-28\nserver.tool(\n  'orders_search',\n  { description: 'Search orders for one customer.', inputSchema: ordersSearchSchema, annotations: { readOnlyHint: true } },\n  async input => ({ content: [{ type: 'text', text: JSON.stringify(await runOrdersSearch(input)) }] }),\n);\n// Local hosts connect over stdio; remote hosts over Streamable HTTP with OAuth.",
