        example: "- An eval asserts the agent's patch makes the suite pass, in under twelve turns, without calling db_write\n- A rubric judge scores answer groundedness 1-5, validated against fifty human labels first\n- OTEL traces show one search tool accounting for 60% of tokens because it returned whole records\n- p95 turns rising from 9 to 19 after a prompt edit fails the CI gate\n- A weekly review of twenty sampled sessions finds three injection attempts, all blocked",
        code: "// An agent eval: outcome, trajectory and cost are all assertions.\nimport { test, expect } from 'vitest';\nimport { runAgent } from '../src/agent';\nimport { TASKS } from './reference-set';           // real tasks with known-good outcomes\n\ntest.each(TASKS)('$id', async task => {\n  const run = await runAgent({ goal: task.goal, maxTurns: 15, budgetUsd: 0.5 });\n\n  // 1. Outcome: deterministic wherever possible.\n  expect(await task.verify(run)).toBe(true);       // tests pass, row exists, file compiles\n\n  // 2. Trajectory: the path matters, not only the answer.\n  const tools = run.calls.map(c => c.tool);\n  expect(tools).toContain(task.expectedTool);\n  expect(tools).not.toContain('db_write');         // forbidden for this task type\n  expect(run.turns).toBeLessThanOrEqual(task.turnBudget);\n\n  // 3. Cost: a regression in tokens is a regression.\n  expect(run.costUsd).toBeLessThanOrEqual(task.costBudget);\n});\n\n// A rubric judge, used only where correctness is qualitative — and validated first.\nexport async function judgeGroundedness(answer: string, sources: string[]) {\n  const { content } = await model.messages.create({\n    model: 'claude-sonnet-5', max_tokens: 256,\n    system: [\n      'Score groundedness 1-5 against the sources only.',\n      '5: every claim is supported by a quoted source. 3: main claims supported, details unsupported.',\n      '1: claims contradict or are absent from the sources. Reply as JSON: { \"score\": n, \"why\": \"...\" }',\n    ].join('\\n'),\n    messages: [{ role: 'user', content: `ANSWER:\\n${answer}\\n\\nSOURCES:\\n${sources.join('\\n---\\n')}` }],\n  });\n  return JSON.parse(content[0].type === 'text' ? content[0].text : '{}') as { score: number; why: string };\n}\n\n// Operations: one span per turn, one child span per tool call.\nimport { trace } from '@opentelemetry/api';\nconst tracer = trace.getTracer('agent');\n\nexport async function tracedTurn(sessionId: string, turn: number, run: () => Promise<TurnResult>) {\n  return tracer.startActiveSpan(`agent.turn`, async span => {\n    span.setAttributes({ 'session.id': sessionId, 'agent.turn': turn });\n    const result = await run();\n    span.setAttributes({\n      'gen_ai.usage.input_tokens': result.inputTokens,\n      'gen_ai.usage.output_tokens': result.outputTokens,\n      'agent.cost_usd': result.costUsd,\n      'agent.tools': result.calls.map(c => c.tool).join(','),\n    });\n    span.end();\n    return result;\n  });\n}",
